UPDATE player_transfers pt
LEFT JOIN players p ON LOWER(p.player_name) = LOWER(pt.player_name)
SET pt.player_id = p.player_id
WHERE pt.player_id IS NULL AND p.player_id IS NOT NULL;

UPDATE player_transfers pt
LEFT JOIN teams t ON LOWER(t.team_name) = LOWER(pt.from_team_name)
SET pt.from_team_id = t.team_id
WHERE pt.from_team_id IS NULL AND t.team_id IS NOT NULL;

UPDATE player_transfers pt
LEFT JOIN teams t ON LOWER(t.team_name) = LOWER(pt.to_team_name)
SET pt.to_team_id = t.team_id
WHERE pt.to_team_id IS NULL AND t.team_id IS NOT NULL;
